     1	import { serverError } from './http.js';
     2	import * as roomsList from './routes/rooms-list.js';
     3	import * as roomsGet from './routes/rooms-get.js';
     4	import * as roomsUpdate from './routes/rooms-update.js';
     5	import * as bookingsList from './routes/bookings-list.js';
     6	import * as bookingsCreate from './routes/bookings-create.js';
     7	import * as bookingsCancel from './routes/bookings-cancel.js';
     8	import * as invoicesGet from './routes/invoices-get.js';
     9	import * as remindersSend from './routes/reminders-send.js';
    10	import * as usersMe from './routes/users-me.js';
    11	import * as health from './routes/health.js';
    12	
    13	export const routes = {
    14	  'rooms-list': roomsList.handle,
    15	  'rooms-get': roomsGet.handle,
    16	  'rooms-update': roomsUpdate.handle,
    17	  'bookings-list': bookingsList.handle,
    18	  'bookings-create': bookingsCreate.handle,
    19	  'bookings-cancel': bookingsCancel.handle,
    20	  'invoices-get': invoicesGet.handle,
    21	  'reminders-send': remindersSend.handle,
    22	  'users-me': usersMe.handle,
    23	  health: health.handle,
    24	};
    25	
    26	// One request: the route's handler, or a 404. An exception the handler does not catch becomes the same 500.
    27	export async function dispatch(name, req, deps) {
    28	  const handle = routes[name];
    29	  if (!handle) return { status: 404, body: { error: 'no such route' } };
    30	  try {
    31	    return await handle(req, deps);
    32	  } catch (err) {
    33	    return serverError(name, err);
    34	  }
    35	}
