     3	export const INTERNAL_ERROR = 'internal error';
     4	
     5	// A 500 response: the body is a fixed text, the exception goes to the log only.
     6	export function serverError(where, err) {
     7	  logError(where, err);
     8	  return { status: 500, body: { error: INTERNAL_ERROR } };
     9	}
