     1	// The error log of the server. Tests read `logged`; the deployed server ships it to the log store.
     2	export const logged = [];
     3	
     4	export function logError(where, err) {
     5	  logged.push({ where, detail: err instanceof Error ? err.stack : String(err) });
     6	}
