     1	import { test } from 'node:test';
     2	import assert from 'node:assert/strict';
     3	import { dispatch } from '../src/app.js';
     4	import { logged } from '../src/logger.js';
     5	
     6	const room = { id: 'r1', name: 'Maple' };
     7	const deps = {
     8	  rooms: { all: async () => [room], find: async (id) => (id === 'r1' ? room : null), update: async (id, v) => ({ id, ...v }) },
     9	  bookings: { forRoom: async () => [{ id: 'b1', roomId: 'r1', date: '2026-12-01' }], create: async (b) => ({ id: 'b2', ...b }), cancel: async () => {} },
    10	  invoices: { find: async (id) => ({ id, total: 12000 }) },
    11	  mailer: { sendReminders: async () => 3 },
    12	  users: { find: async (id) => ({ id, name: 'Aki' }) },
    13	  db: { ping: async () => {} },
    14	};
    15	
    16	test('a room is found', async () => {
    17	  assert.deepEqual(await dispatch('rooms-get', { params: { id: 'r1' } }, deps), { status: 200, body: room });
    18	});
    19	
    20	test('an unknown room is a 404', async () => {
    21	  assert.equal((await dispatch('rooms-get', { params: { id: 'zz' } }, deps)).status, 404);
    22	});
    23	
    24	test('a booking is created', async () => {
    25	  const r = await dispatch('bookings-create', { body: { roomId: 'r1', date: '2026-12-01' } }, deps);
    26	  assert.equal(r.status, 201);
    27	  assert.equal(r.body.roomId, 'r1');
    28	});
    29	
    30	test('a booking without a date is a 400', async () => {
    31	  assert.equal((await dispatch('bookings-create', { body: { roomId: 'r1' } }, deps)).status, 400);
    32	});
    33	
    34	test('reminders are sent for a day', async () => {
    35	  assert.deepEqual(await dispatch('reminders-send', { query: { date: '2026-12-01' } }, deps), { status: 200, body: { sent: 3 } });
    36	});
    37	
    38	test('an unknown route is a 404', async () => {
    39	  assert.equal((await dispatch('nope', {}, deps)).status, 404);
    40	});
    41	
    42	test('the room list answers a fixed text when the store fails, and logs the error', async () => {
    43	  const failing = { ...deps, rooms: { all: async () => { throw new Error('SQLITE_BUSY: database is locked'); } } };
    44	  const r = await dispatch('rooms-list', {}, failing);
    45	  assert.deepEqual(r, { status: 500, body: { error: 'internal error' } });
    46	  assert.match(logged.at(-1).detail, /SQLITE_BUSY/);
    47	});

