import { serverError } from '../http.js';

// DELETE /bookings/:id
export async function handle(req, deps) {
  try {
    await deps.bookings.cancel(req.params.id);
    return { status: 204, body: null };
  } catch (err) {
    return serverError('bookings-cancel', err);
  }
}

src/routes/bookings-create.js.text:
import { serverError } from '../http.js';

// POST /bookings
export async function handle(req, deps) {
  const { roomId, date } = req.body ?? {};
  if (!roomId || !date) return { status: 400, body: { error: 'roomId and date are required' } };
  try {
    const booking = await deps.bookings.create({ roomId, date });
    return { status: 201, body: booking };
  } catch (err) {
    return serverError('bookings-create', err);
  }
}

