import { serverError } from '../http.js';

// GET /rooms/:id/bookings
export async function handle(req, deps) {
  try {
    return { status: 200, body: await deps.bookings.forRoom(req.params.id) };
  } catch (err) {
    return serverError('bookings-list', err);
  }
}

