import { test } from 'node:test';
import assert from 'node:assert/strict';
import { dispatch, routes } from '../src/app.js';
import { logged } from '../src/logger.js';

const room = { id: 'r1', name: 'Maple' };
const deps = {
  rooms: { all: async () => [room], find: async (id) => (id === 'r1' ? room : null), update: async (id, v) => ({ id, ...v }) },
  bookings: { forRoom: async () => [{ id: 'b1', roomId: 'r1', date: '2026-12-01' }], create: async (b) => ({ id: 'b2', ...b }), cancel: async () => {} },
  invoices: { find: async (id) => ({ id, total: 12000 }) },
  mailer: { sendReminders: async () => 3 },
  users: { find: async (id) => ({ id, name: 'Aki' }) },
  db: { ping: async () => {} },
};

test('a room is found', async () => {
  assert.deepEqual(await dispatch('rooms-get', { params: { id: 'r1' } }, deps), { status: 200, body: room });
});

test('an unknown room is a 404', async () => {
  assert.equal((await dispatch('rooms-get', { params: { id: 'zz' } }, deps)).status, 404);
});

test('a booking is created', async () => {
  const r = await dispatch('bookings-create', { body: { roomId: 'r1', date: '2026-12-01' } }, deps);
  assert.equal(r.status, 201);
  assert.equal(r.body.roomId, 'r1');
});

test('a booking without a date is a 400', async () => {
  assert.equal((await dispatch('bookings-create', { body: { roomId: 'r1' } }, deps)).status, 400);
});

test('reminders are sent for a day', async () => {
  assert.deepEqual(await dispatch('reminders-send', { query: { date: '2026-12-01' } }, deps), { status: 200, body: { sent: 3 } });
});

test('an unknown route is a 404', async () => {
  assert.equal((await dispatch('nope', {}, deps)).status, 404);
});

test('the room list answers a fixed text when the store fails, and logs the error', async () => {
  const failing = { ...deps, rooms: { all: async () => { throw new Error('SQLITE_BUSY: database is locked'); } } };
  const r = await dispatch('rooms-list', {}, failing);
  assert.deepEqual(r, { status: 500, body: { error: 'internal error' } });
  assert.match(logged.at(-1).detail, /SQLITE_BUSY/);
});

// The answers that issue #31 must not change, for the routes whose error handling it touches.
test('a booking is cancelled', async () => {
  assert.deepEqual(await dispatch('bookings-cancel', { params: { id: 'b1' } }, deps), { status: 204, body: null });
});

test('the bookings of a room are listed', async () => {
  assert.deepEqual(await dispatch('bookings-list', { params: { id: 'r1' } }, deps), {
    status: 200,
    body: [{ id: 'b1', roomId: 'r1', date: '2026-12-01' }],
  });
});

test('an invoice is found', async () => {
  assert.deepEqual(await dispatch('invoices-get', { params: { id: 'i1' } }, deps), { status: 200, body: { id: 'i1', total: 12000 } });
});

test('an unknown invoice is a 404', async () => {
  const none = { ...deps, invoices: { find: async () => null } };
  assert.deepEqual(await dispatch('invoices-get', { params: { id: 'zz' } }, none), { status: 404, body: { error: 'invoice not found' } });
});

test('the profile of the signed-in user is returned', async () => {
  assert.deepEqual(await dispatch('users-me', { user: { id: 'u1' } }, deps), { status: 200, body: { id: 'u1', name: 'Aki' } });
});

test('the profile without a sign-in is a 401', async () => {
  assert.deepEqual(await dispatch('users-me', {}, deps), { status: 401, body: { error: 'sign in first' } });
});

test('reminders without a date are a 400', async () => {
  assert.deepEqual(await dispatch('reminders-send', {}, deps), { status: 400, body: { error: 'date is required' } });
});

// Issue #31: when a store fails, the body is the fixed text only; the exception goes to the log.
const fail = async () => { throw new Error('SQLITE_BUSY: database is locked (/srv/booking/data.db)'); };
const failing = {
  rooms: { all: fail, find: fail, update: fail },
  bookings: { forRoom: fail, create: fail, cancel: fail },
  invoices: { find: fail },
  mailer: { sendReminders: fail },
  users: { find: fail },
  db: { ping: fail },
};
const failureRequests = {
  'rooms-list': {},
  'rooms-get': { params: { id: 'r1' } },
  'rooms-update': { params: { id: 'r1' }, body: { name: 'Oak' } },
  'bookings-list': { params: { id: 'r1' } },
  'bookings-create': { body: { roomId: 'r1', date: '2026-12-01' } },
  'bookings-cancel': { params: { id: 'b1' } },
  'invoices-get': { params: { id: 'i1' } },
  'users-me': { user: { id: 'u1' } },
  health: {},
};

for (const [name, req] of Object.entries(failureRequests)) {
  test(`${name} answers a fixed text when its store fails, and logs the error`, async () => {
    const r = await dispatch(name, req, failing);
    assert.deepEqual(r, { status: 500, body: { error: 'internal error' } });
    assert.equal(logged.at(-1)?.where, name);
    assert.match(logged.at(-1).detail, /SQLITE_BUSY/);
  });
}

// reminders-send answers 502, not 500, when the mailer fails: the same rule, with its own fixed text.
test('reminders-send answers a fixed text when the mailer fails, and logs the error', async () => {
  const r = await dispatch('reminders-send', { query: { date: '2026-12-01' } }, failing);
  assert.deepEqual(r, { status: 502, body: { message: 'could not send the reminders' } });
  assert.equal(logged.at(-1)?.where, 'reminders-send');
  assert.match(logged.at(-1).detail, /SQLITE_BUSY/);
});

// A new route needs a failure case here, so that it cannot leak an exception unnoticed.
test('every route has a failure case', () => {
  assert.deepEqual([...Object.keys(failureRequests), 'reminders-send'].sort(), Object.keys(routes).sort());
});
